WITH src AS (SELECT *, CASE WHEN quantity >= 267 THEN 'High' WHEN quantity >= 99 THEN 'Medium' ELSE 'Low' END AS quantity_band FROM inventory WHERE store_id IN (2, 4, 5, 6) AND last_restock < '2024-03-01' AND quantity = 108), summary AS (SELECT QUARTER(last_restock) AS last_restock_quarter, COUNT(quantity) AS quantity_count, MIN(quantity) AS min_quantity FROM src GROUP BY QUARTER(last_restock)) SELECT last_restock_quarter, quantity_count, min_quantity FROM summary ORDER BY min_quantity DESC;
